; CHR ROM: 2 x 4KB pattern tables (chr/chr_0.chr = PPU $0000, chr/chr_1.chr = PPU $1000)
; with the game data that RESET copies to RAM. Generated by tools/disasm.py (tools/chrdata.py).
; Tiles edited in gfx/sheet_00.png reach the ROM through chr/*.chr; the data blocks below are taken
; from this file, so their bytes in the .chr files / PNG are ignored.

.segment "CHR_ROM"

  .incbin "chr/chr_0.chr", $0000, CHR_SONGS

; PPU $098E-$0A3F -> RAM $014E-$01FF: tune pointers (PPU addresses) + tunes 1-3
.org $014E
songTable:                        ; tune 0 (extra life, in PRG) is filled in by InitMusicPtr
  .word 0, TuneFlagshipHit+SONG_PTR_BIAS, TuneAlienHit+SONG_PTR_BIAS, TuneGameStart+SONG_PTR_BIAS
TuneGameStart:                    ; tune 3, 84 notes
  .byte DUR_1|NOTE_As6, DUR_1|NOTE_A6, DUR_1|NOTE_G6, DUR_1|NOTE_F6, DUR_1|NOTE_Ds6, DUR_1|NOTE_D6
  .byte DUR_1|NOTE_C6, DUR_1|NOTE_As5, DUR_1|NOTE_A5, DUR_1|NOTE_G5, DUR_1|NOTE_F5, DUR_4|NOTE_F4
  .byte DUR_4|NOTE_As4, DUR_4|NOTE_F4, DUR_4|NOTE_As4, DUR_4|NOTE_D5, DUR_4|NOTE_As4, DUR_4|NOTE_D5
  .byte DUR_4|NOTE_F5, DUR_4|NOTE_D5, DUR_4|NOTE_F5, DUR_8|NOTE_As5, DUR_8|NOTE_REST, DUR_4|NOTE_F4
  .byte DUR_4|NOTE_As4, DUR_4|NOTE_F4, DUR_4|NOTE_As4, DUR_4|NOTE_D5, DUR_4|NOTE_As4, DUR_4|NOTE_D5
  .byte DUR_4|NOTE_F5, DUR_4|NOTE_D5, DUR_4|NOTE_F5, DUR_8|NOTE_As5, DUR_8|NOTE_REST, DUR_4|NOTE_D5
  .byte DUR_2|NOTE_C5, DUR_2|NOTE_Cs5, DUR_2|NOTE_C5, DUR_2|NOTE_Cs5, DUR_2|NOTE_C5, DUR_2|NOTE_Cs5
  .byte DUR_2|NOTE_C5, DUR_2|NOTE_Cs5, DUR_2|NOTE_C5, DUR_2|NOTE_Cs5, DUR_2|NOTE_C5, DUR_2|NOTE_Cs5
  .byte DUR_2|NOTE_C5, DUR_2|NOTE_Cs5, DUR_2|NOTE_C5, DUR_2|NOTE_Cs5, DUR_1|NOTE_As4, DUR_1|NOTE_C5
  .byte DUR_1|NOTE_D5, DUR_1|NOTE_Ds5, DUR_1|NOTE_F5, DUR_1|NOTE_G5, DUR_1|NOTE_A5, DUR_1|NOTE_As5
  .byte DUR_1|NOTE_As4, DUR_1|NOTE_C5, DUR_1|NOTE_D5, DUR_1|NOTE_Ds5, DUR_1|NOTE_F5, DUR_1|NOTE_G5
  .byte DUR_1|NOTE_A5, DUR_1|NOTE_As5, DUR_1|NOTE_As4, DUR_1|NOTE_C5, DUR_1|NOTE_D5, DUR_1|NOTE_Ds5
  .byte DUR_1|NOTE_F5, DUR_1|NOTE_G5, DUR_1|NOTE_A5, DUR_1|NOTE_As5, DUR_1|NOTE_As4, DUR_1|NOTE_C5
  .byte DUR_1|NOTE_D5, DUR_1|NOTE_Ds5, DUR_1|NOTE_F5, DUR_1|NOTE_G5, DUR_1|NOTE_A5, DUR_1|NOTE_As5
  .byte SONG_END
TuneAlienHit:                     ; tune 2, 33 notes
  .byte DUR_1|NOTE_G5, DUR_1|NOTE_F5, DUR_1|NOTE_Ds5, DUR_1|NOTE_D5, DUR_1|NOTE_C5, DUR_1|NOTE_As4
  .byte DUR_1|NOTE_G5, DUR_1|NOTE_F5, DUR_1|NOTE_Ds5, DUR_1|NOTE_D5, DUR_1|NOTE_C5, DUR_1|NOTE_As4
  .byte DUR_1|NOTE_As4, DUR_1|NOTE_C5, DUR_1|NOTE_D5, DUR_1|NOTE_Ds5, DUR_1|NOTE_F5, DUR_1|NOTE_G5
  .byte DUR_1|NOTE_A5, DUR_1|NOTE_As5, DUR_1|NOTE_C6, DUR_1|NOTE_D6, DUR_1|NOTE_Ds6, DUR_1|NOTE_F6
  .byte DUR_1|NOTE_G6, DUR_1|NOTE_A6, DUR_1|NOTE_G6, DUR_1|NOTE_F6, DUR_1|NOTE_Ds6, DUR_1|NOTE_D6
  .byte DUR_1|NOTE_C6, DUR_1|NOTE_D6, DUR_1|NOTE_Ds6, SONG_END
TuneFlagshipHit:                  ; tune 1, 50 notes
  .byte DUR_1|NOTE_As4, DUR_1|NOTE_A4, DUR_1|NOTE_G4, DUR_1|NOTE_F4, DUR_1|NOTE_G4, DUR_1|NOTE_As4
  .byte DUR_1|NOTE_C5, DUR_1|NOTE_D5, DUR_1|NOTE_Ds5, DUR_1|NOTE_F5, DUR_1|NOTE_Fs5, DUR_2|NOTE_REST
  .byte DUR_1|NOTE_F5, DUR_1|NOTE_Ds5, DUR_1|NOTE_D5, DUR_1|NOTE_C5, DUR_1|NOTE_As4, DUR_1|NOTE_C5
  .byte DUR_1|NOTE_Ds5, DUR_1|NOTE_F5, DUR_1|NOTE_G5, DUR_1|NOTE_A5, DUR_1|NOTE_As5, DUR_1|NOTE_B5
  .byte DUR_2|NOTE_REST, DUR_1|NOTE_As5, DUR_1|NOTE_A5, DUR_1|NOTE_G5, DUR_1|NOTE_F5, DUR_1|NOTE_G5
  .byte DUR_1|NOTE_As5, DUR_1|NOTE_C6, DUR_1|NOTE_D6, DUR_1|NOTE_Ds6, DUR_1|NOTE_F6, DUR_1|NOTE_Fs6
  .byte DUR_2|NOTE_REST, DUR_1|NOTE_F6, DUR_1|NOTE_Ds6, DUR_1|NOTE_D6, DUR_1|NOTE_C6, DUR_1|NOTE_As5
  .byte DUR_1|NOTE_C6, DUR_1|NOTE_Ds6, DUR_1|NOTE_F6, DUR_1|NOTE_G6, DUR_1|NOTE_A6, DUR_1|NOTE_As6
  .byte DUR_1|NOTE_B6, DUR_2|NOTE_Gs6, SONG_END
  .assert * = songTable+SONG_DATA_SIZE, error, "tune block must end at $0200"
.reloc
  .incbin "chr/chr_0.chr", CHR_SONGS+SONG_DATA_SIZE

  .incbin "chr/chr_1.chr", $0000, CHR_GAME_DATA-CHR_TABLE1

; PPU $1480-$17FF -> RAM $0300-$067F: text pointers (PPU addresses) + text records (PrintText)
.charmap $20, $40                  ; normal font: tile = char - TEXT_BIAS_ASCII, space = $40
.charmap $2D, $5B
.charmap $2E, $5C
.org $0300
chrData:
  .byte $00                        ; unused
textPtrs:                         ; PrintText: text number -> record, as a PPU address (RAM + TEXT_PTR_BIAS)
  .word Txt1Up+TEXT_PTR_BIAS         ; $00 TXT_1UP
  .word TxtHiscore+TEXT_PTR_BIAS     ; $01 TXT_HISCORE
  .word Txt2Up+TEXT_PTR_BIAS         ; $02 TXT_2UP
  .word TxtMission+TEXT_PTR_BIAS     ; $03 TXT_MISSION
  .word TxtWeAreTheGalaxians+TEXT_PTR_BIAS ; $04
  .word TxtScoreTable+TEXT_PTR_BIAS  ; $05 TXT_SCORE_TABLE
  .word TxtConvoyCharger+TEXT_PTR_BIAS ; $06
  .word Txt1Player+TEXT_PTR_BIAS     ; $07 TXT_1_PLAYER
  .word Txt2Players+TEXT_PTR_BIAS    ; $08
  .word TxtC19791984NamcoLtd+TEXT_PTR_BIAS ; $09
  .word TxtRights+TEXT_PTR_BIAS      ; $0A TXT_RIGHTS
  .word TxtLogo0+TEXT_PTR_BIAS       ; $0B TXT_LOGO0
  .word TxtLogo1+TEXT_PTR_BIAS       ; $0C
  .word TxtLogo2+TEXT_PTR_BIAS       ; $0D
  .word TxtLogo3+TEXT_PTR_BIAS       ; $0E
  .word TxtLogo4+TEXT_PTR_BIAS       ; $0F
  .word TxtLogo5+TEXT_PTR_BIAS       ; $10
  .word TxtPlayer1+TEXT_PTR_BIAS     ; $11 TXT_PLAYER1
  .word TxtPlayer2+TEXT_PTR_BIAS     ; $12
  .word TxtGameOver+TEXT_PTR_BIAS    ; $13 TXT_GAME_OVER
  .word TxtReady+TEXT_PTR_BIAS       ; $14 TXT_READY
  .word TxtPause+TEXT_PTR_BIAS       ; $15 TXT_PAUSE
  .word TxtLogoNamcot+TEXT_PTR_BIAS  ; $16 TXT_LOGO_NAMCOT
  .word TxtBonus150+TEXT_PTR_BIAS    ; $17 TXT_BONUS_150
  .word TxtBonus200+TEXT_PTR_BIAS    ; $18
  .word TxtBonus300+TEXT_PTR_BIAS    ; $19
  .word TxtBonus800+TEXT_PTR_BIAS    ; $1A
  .word TxtScoreRow0+TEXT_PTR_BIAS   ; $1B TXT_SCORE_ROW0
  .word TxtScoreRow1+TEXT_PTR_BIAS   ; $1C
  .word TxtScoreRow2+TEXT_PTR_BIAS   ; $1D
  .word TxtScoreRow3+TEXT_PTR_BIAS   ; $1E
  .word Txt2UpLeft+TEXT_PTR_BIAS     ; $1F TXT_2UP_LEFT
  .word TxtBlankRow20+TEXT_PTR_BIAS  ; $20 TXT_BLANK_ROW20
  .word TxtBlankRow18+TEXT_PTR_BIAS  ; $21 TXT_BLANK_ROW18
  .word TxtBorder+TEXT_PTR_BIAS      ; $22 TXT_BORDER
  .res 57, $FF                     ; free
TxtBorder:                        ; tiles (printed with textCharBias = 0)
  .byte 7, 3, $33, $31, $31, $31, $31, $31, $31, $31, $31, $31, $31, $31, $31, $31, $31, $31, $31, $31, $35, TEXT_END
TxtLogo0:                         ; tiles (printed with textCharBias = 0)
  .byte 8, 3, $2E, $FF, $FF, $38, $39, $3A, $3B, $3C, $3D, $3E, $3F, $68, $69, $6A, $6B, $FF, $6C, $6D, $2F, TEXT_END
TxtLogo1:                         ; tiles (printed with textCharBias = 0)
  .byte 9, 3, $2E, $C0, $C1, $C2, $C3, $C4, $C5, $C6, $FF, $FF, $FF, $FF, $FF, $C7, $C8, $C9, $CA, $CB, $2F, TEXT_END
TxtLogo2:                         ; tiles (printed with textCharBias = 0)
  .byte 10, 3, $2E, $CC, $CD, $CE, $CF, $D0, $D1, $D2, $D3, $D4, $D5, $D6, $D7, $D8, $D9, $DA, $DB, $DC, $2F, TEXT_END
TxtLogo3:                         ; tiles (printed with textCharBias = 0)
  .byte 11, 3, $2E, $DD, $DE, $DF, $E0, $E1, $E2, $E3, $E4, $E5, $E6, $E7, $E8, $E9, $EA, $EB, $EC, $ED, $2F, TEXT_END
TxtLogo4:                         ; tiles (printed with textCharBias = 0)
  .byte 12, 3, $2E, $EE, $EF, $F0, $F1, $F2, $F3, $F4, $F5, $F6, $F7, $F8, $F9, $FA, $FB, $FC, $FD, $FE, $2F, TEXT_END
TxtLogo5:                         ; tiles (printed with textCharBias = 0)
  .byte 21, 8, $90, $91, $92, $93, $94, $95, $96, $97, $98, TEXT_END
TxtLogoNamcot:                    ; tiles (printed with textCharBias = 0)
  .byte 26, 8, $90, $91, $92, $93, $94, $95, $96, $97, $98, TEXT_END
Txt1Up:                           ; "1UP"
  .byte 3, 2, ":UP", TEXT_END
TxtHiscore:                       ; "HI-SCORE"
  .byte 3, 9, "HI-SCORE", TEXT_END
Txt2Up:                           ; "2UP"
  .byte 3, 20, ";UP", TEXT_END
TxtMission:                       ; "MISSION: DESTROY ALIENS"
  .byte 7, 1, "MISSION", CHAR_COLON, " DESTROY ALIENS", TEXT_END
TxtWeAreTheGalaxians:             ; "WE ARE THE GALAXIANS"
  .byte 9, 3, "WE ARE THE GALAXIANS", TEXT_END
TxtScoreTable:                    ; "- SCORE ADVANCE TABLE -"
  .byte 12, 1, "- SCORE ADVANCE TABLE -", TEXT_END
  .res chrData+CHR_ICONS-CHR_GAME_DATA-*, $FF
chrTiles:                         ; tiles $60-$6F: graphics (HUD icons), copied to RAM too
  .incbin "chr/chr_1.chr", CHR_ICONS-CHR_TABLE1, $100
TxtConvoyCharger:                 ; "CONVOY  CHARGER"
  .byte 14, 5, "CONVOY  CHARGER", TEXT_END
Txt1Player:                       ; "1 PLAYER"
  .byte 16, 9, ": PLAYER", TEXT_END
Txt2Players:                      ; "2 PLAYERS"
  .byte 18, 9, "; PLAYERS", TEXT_END
TxtC19791984NamcoLtd:             ; "(c)1979 1984 NAMCO LTD."
  .byte 24, 2, "]:?=? :?>< NAMCO LTD.", TEXT_END
TxtRights:                        ; "ALL RIGHTS RESERVED"
  .byte 26, 3, "ALL RIGHTS RESERVED", TEXT_END
TxtPlayer1:                       ; "PLAYER 1"
  .byte 18, 9, "PLAYER :", TEXT_END
TxtPlayer2:                       ; "PLAYER 2"
  .byte 18, 9, "PLAYER ;", TEXT_END
TxtGameOver:                      ; "GAME  OVER"
  .byte 20, 8, "GAME  OVER", TEXT_END
TxtReady:                         ; "READY"
  .byte 20, 10, "READY", TEXT_END
TxtPause:                         ; "PAUSE"
  .byte 20, 10, "PAUSE", TEXT_END
TxtBonus150:                      ; "150"
  .byte 17, 16, "150", TEXT_END
TxtBonus200:                      ; "200"
  .byte 17, 16, "200", TEXT_END
TxtBonus300:                      ; "300"
  .byte 17, 16, "300", TEXT_END
TxtBonus800:                      ; "800"
  .byte 17, 16, "800", TEXT_END
TxtScoreRow0:                     ; "60           PTS"
  .byte 17, 7, "60           ", CHAR_PTS, CHAR_PTS+1, CHAR_PTS+2, TEXT_END
TxtScoreRow1:                     ; "50       100 PTS"
  .byte 19, 7, "50       100 ", CHAR_PTS, CHAR_PTS+1, CHAR_PTS+2, TEXT_END
TxtScoreRow2:                     ; "40        80 PTS"
  .byte 21, 7, "40        80 ", CHAR_PTS, CHAR_PTS+1, CHAR_PTS+2, TEXT_END
TxtScoreRow3:                     ; "30        60 PTS"
  .byte 23, 7, "30        60 ", CHAR_PTS, CHAR_PTS+1, CHAR_PTS+2, TEXT_END
Txt2UpLeft:                       ; "2UP"
  .byte 3, 2, ";UP", TEXT_END
TxtBlankRow20:                    ; ""
  .byte 20, 0, TEXT_END
TxtBlankRow18:                    ; ""
  .byte 18, 0, TEXT_END
  .res chrData+CHR_GAME_DATA_SIZE-*, $FF
  .assert * = chrData+CHR_GAME_DATA_SIZE, error, "text block must end at $0680"
.charmap $20, $20
.charmap $2D, $2D
.charmap $2E, $2E
.reloc
  .incbin "chr/chr_1.chr", CHR_GAME_DATA+CHR_GAME_DATA_SIZE-CHR_TABLE1

